-- Metadata only. No business rows, role passwords, sequence current values or raw definitions emitted.
-- Managed schema differences require separate environment classification.
WITH ns AS (
 SELECT oid,nspname FROM pg_namespace WHERE nspname IN ('public','app_private','auth','storage','extensions')
), rel AS (
 SELECT c.*,n.nspname FROM pg_class c JOIN ns n ON n.oid=c.relnamespace WHERE c.relkind IN ('r','p','v','m','S','f')
), objects AS (
 SELECT 'schemas' AS kind,n.nspname AS object_key,jsonb_build_array(pg_get_userbyid(p.nspowner))::text AS definition FROM ns n JOIN pg_namespace p ON p.oid=n.oid
 UNION ALL SELECT 'schema_grants',n.nspname,jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable)::text FROM ns n JOIN pg_namespace p ON p.oid=n.oid CROSS JOIN LATERAL aclexplode(COALESCE(p.nspacl,acldefault('n',p.nspowner))) a
 UNION ALL SELECT 'types:'||n.nspname,t.typname,jsonb_build_array(t.typtype,t.typcategory,t.typnotnull,t.typdefault,CASE WHEN t.typbasetype<>0 THEN format_type(t.typbasetype,t.typtypmod) END,pg_get_userbyid(t.typowner),t.typacl::text)::text FROM pg_type t JOIN ns n ON n.oid=t.typnamespace
 UNION ALL SELECT 'enum_labels:'||n.nspname,t.typname,jsonb_build_array(e.enumsortorder,e.enumlabel)::text FROM pg_enum e JOIN pg_type t ON t.oid=e.enumtypid JOIN ns n ON n.oid=t.typnamespace
 UNION ALL SELECT 'domain_constraints:'||n.nspname,t.typname||'.'||k.conname,pg_get_constraintdef(k.oid,false) FROM pg_constraint k JOIN pg_type t ON t.oid=k.contypid JOIN ns n ON n.oid=t.typnamespace
 UNION ALL SELECT 'sequences:'||r.nspname,r.relname,jsonb_build_array(format_type(s.seqtypid,NULL),s.seqstart,s.seqincrement,s.seqmax,s.seqmin,s.seqcache,s.seqcycle)::text FROM pg_sequence s JOIN rel r ON r.oid=s.seqrelid
 UNION ALL SELECT 'column_grants:'||r.nspname,r.relname||'.'||a.attname,jsonb_build_array(pg_get_userbyid(g.grantor),CASE WHEN g.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(g.grantee) END,g.privilege_type,g.is_grantable)::text FROM rel r JOIN pg_attribute a ON a.attrelid=r.oid CROSS JOIN LATERAL aclexplode(a.attacl) g WHERE a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT 'default_grants',COALESCE(n.nspname,'GLOBAL')||':'||pg_get_userbyid(d.defaclrole)||':'||d.defaclobjtype::text,jsonb_build_array(pg_get_userbyid(g.grantor),CASE WHEN g.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(g.grantee) END,g.privilege_type,g.is_grantable)::text FROM pg_default_acl d LEFT JOIN ns n ON n.oid=d.defaclnamespace CROSS JOIN LATERAL aclexplode(d.defaclacl) g WHERE d.defaclnamespace=0 OR n.oid IS NOT NULL
 UNION ALL SELECT 'role_memberships',parent.rolname||':'||member.rolname,jsonb_build_array(grantor.rolname,m.admin_option,m.inherit_option,m.set_option)::text FROM pg_auth_members m JOIN pg_roles parent ON parent.oid=m.roleid JOIN pg_roles member ON member.oid=m.member JOIN pg_roles grantor ON grantor.oid=m.grantor WHERE parent.rolname IN ('anon','authenticated','service_role','authenticator','postgres','supabase_admin','supabase_auth_admin','supabase_storage_admin') OR member.rolname IN ('anon','authenticated','service_role','authenticator','postgres','supabase_admin','supabase_auth_admin','supabase_storage_admin')
 UNION ALL SELECT 'role_attributes',rolname,jsonb_build_array(rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls)::text FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role','authenticator','postgres','supabase_admin','supabase_auth_admin','supabase_storage_admin')
 UNION ALL SELECT 'partitions:'||r.nspname,r.relname,jsonb_build_array(pg_get_expr(r.relpartbound,r.oid),CASE WHEN r.relkind='p' THEN pg_get_partkeydef(r.oid) END,ARRAY(SELECT pn.nspname||'.'||pc.relname FROM pg_inherits i JOIN pg_class pc ON pc.oid=i.inhparent JOIN pg_namespace pn ON pn.oid=pc.relnamespace WHERE i.inhrelid=r.oid ORDER BY 1))::text FROM rel r WHERE r.relispartition OR r.relkind='p'
 UNION ALL SELECT 'relations:'||r.nspname,r.relname,jsonb_build_array(r.relkind,r.relrowsecurity,r.relforcerowsecurity,pg_get_userbyid(r.relowner),r.reloptions)::text FROM rel r
 UNION ALL SELECT 'columns:'||r.nspname,r.relname||'.'||a.attname,jsonb_build_array(a.attnum,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,pg_get_expr(d.adbin,d.adrelid),CASE WHEN a.attcollation<>0 THEN a.attcollation::regcollation::text END)::text FROM rel r JOIN pg_attribute a ON a.attrelid=r.oid LEFT JOIN pg_attrdef d ON d.adrelid=r.oid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT 'constraints:'||r.nspname,r.relname||'.'||k.conname,jsonb_build_array(pg_get_constraintdef(k.oid,false),k.convalidated,k.condeferrable,k.condeferred)::text FROM rel r JOIN pg_constraint k ON k.conrelid=r.oid
 UNION ALL SELECT 'indexes:'||r.nspname,i.relname,jsonb_build_array(pg_get_indexdef(i.oid),x.indisvalid,x.indisready)::text FROM rel r JOIN pg_index x ON x.indrelid=r.oid JOIN pg_class i ON i.oid=x.indexrelid
 UNION ALL SELECT 'policies:'||r.nspname,r.relname||'.'||p.polname,jsonb_build_array(p.polcmd,p.polpermissive,ARRAY(SELECT CASE WHEN role_oid=0 THEN 'PUBLIC' ELSE pg_get_userbyid(role_oid) END FROM unnest(p.polroles) AS role_oid ORDER BY 1),pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid))::text FROM rel r JOIN pg_policy p ON p.polrelid=r.oid
 UNION ALL SELECT 'routines:'||n.nspname,p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',jsonb_build_array(pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),p.prosecdef,p.proconfig)::text FROM pg_proc p JOIN ns n ON n.oid=p.pronamespace WHERE p.prokind IN ('f','p','w')
 UNION ALL SELECT 'triggers:'||r.nspname,r.relname||'.'||t.tgname,jsonb_build_array(pg_get_triggerdef(t.oid,false),t.tgenabled)::text FROM rel r JOIN pg_trigger t ON t.tgrelid=r.oid WHERE NOT t.tgisinternal
 UNION ALL SELECT 'views:'||r.nspname,r.relname,pg_get_viewdef(r.oid,false) FROM rel r WHERE r.relkind IN ('v','m')
 UNION ALL SELECT 'relation_grants:'||r.nspname,r.relname,jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable)::text FROM rel r CROSS JOIN LATERAL aclexplode(COALESCE(r.relacl,acldefault(CASE WHEN r.relkind='S' THEN 's'::"char" ELSE 'r'::"char" END,r.relowner))) a
 UNION ALL SELECT 'routine_grants:'||n.nspname,p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable)::text FROM pg_proc p JOIN ns n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE p.prokind IN ('f','p','w')
) SELECT kind,count(*) AS object_count,md5(string_agg(jsonb_build_array(object_key,definition)::text,E'\n' ORDER BY object_key COLLATE "C",definition COLLATE "C")) AS fingerprint FROM objects GROUP BY kind ORDER BY kind;
